353	                // HoldMode::Cancel (it dropped all pending NoteOns and
354	                // released emitted notes at `now`). That stays the
355	                // default *behavior* if mode resolves to Cancel — the
356	                // FTUX continues to feel performative. Users who want
357	                // canon-style sustained passing tones flip the toggle
358	                // to Forever or NearFuture/PhraseEnd.
359	                let global_hold = world
360	                    .global_hold_mode
361	                    .lock()
362	                    .map(|g| *g)
363	                    .unwrap_or_default();
364	                let effective = self.hold_mode.unwrap_or(global_hold);
365	                let beats_per_bar = world.transport.time_signature().0 as f64;
366	                // PhraseEnd horizon: same idea as CanonLane — let
367	                // pending emissions within the current bar fire.
368	                let phrase_end = (now / beats_per_bar).floor() * beats_per_bar + beats_per_bar;
