374	                    if p.player_note != note {
375	                        return true;
376	                    }
377	                    let keep = match effective {
378	                        HoldMode::Forever => true,
379	                        HoldMode::Cancel => false,
380	                        HoldMode::NearFuture { tail_beats } => (p.fire_at - now) <= tail_beats,
381	                        HoldMode::PhraseEnd => p.fire_at <= phrase_end,
382	                    };
383	                    if !keep {
