390	                    // never produced sound. Already-emitted notes get
391	                    // released at `now`, OR at `now + tail_beats` so
392	                    // the lookahead / sustain semantics feel coherent.
393	                    held.emitted_notes.retain(|n| !canceled_pitches.contains(n));
394	                    let release_at = match effective {
395	                        HoldMode::NearFuture { tail_beats } => now + tail_beats,
396	                        _ => now,
397	                    };
