161	    /// `from`) for use as a weak-beat passing/auxiliary tone in
162	    /// Species 2/3. Falls back to `from` if the scale's bounds reject
163	    /// the step.
164	    fn pick_passing(
165	        &self,
166	        scale: &mut contrapunk_harmony::Scale,
167	        from: Note,
168	        direction: i8,
169	    ) -> Note {
170	        scale.transpose_diatonic(from, direction).unwrap_or(from)
171	    }
