 94	        }
 95	    }
 96	
 97	    /// Clear every lane's in-flight runtime state while preserving its
 98	    /// configuration. This is allocation-free and safe for panic/stop
 99	    /// handling on the processing thread.
100	    pub fn reset_runtime(&mut self) {
101	        for lane in &mut self.lanes {
102	            lane.reset_runtime();
103	        }
104	    }
105	
106	    /// Run one iteration: Sense → Mutate → Decide. Returns the
107	    /// concatenated dispatch ops from all Decide lanes.
108	    ///
109	    /// `engine` is passed in (rather than reaching into
110	    /// `world.engine_snapshot`) so tests can pass an isolated engine
111	    /// without standing up a full `WorldState::new` wiring.
112	    pub fn tick(&mut self, engine: &Mutex<HarmonyEngine>) -> Vec<DispatchOp> {
113	        if !self.enabled.load(Ordering::Acquire) {
114	            return Vec::new();
115	        }
116	
117	        // Phase 1: Sense — write WorldState.
118	        for lane in self
119	            .lanes
120	            .iter_mut()
121	            .filter(|l| l.phase() == LanePhase::Sense)
122	        {
123	            let out = lane.tick(&self.world);
124	            apply_world_writes(&self.world, out.world_writes);
125	        }
126	
127	        // Phase 2: Mutate — write HarmonyEngine.
128	        for lane in self
129	            .lanes
130	            .iter_mut()
131	            .filter(|l| l.phase() == LanePhase::Mutate)
132	        {
133	            let out = lane.tick(&self.world);
134	            if !out.engine_mutations.is_empty() {
135	                let mut e = engine.lock().expect("engine mutex poisoned");
136	                for m in out.engine_mutations {
137	                    apply_engine_mutation(&mut e, m);
138	                }
139	            }
140	        }
190	        .collect();
191	    let mut companion = state.companion.lock().map_err(|e| e.to_string())?;
192	    companion.configure_lane("canon", serde_json::json!({ "voices": voices_json }))
193	}
