197	/// Set the dedicated CounterpointLane's enabled + species + transpose
198	/// + direction in one call. Pure JSON pass-through to
199	/// `Companion::configure_lane("counterpoint", …)`. The Lane merges
200	/// missing fields rather than fully replacing, so callers can send
201	/// just the field they're updating.
202	#[tauri::command]
203	pub fn counterpoint_set_config(
204	    enabled: Option<bool>,
205	    species: Option<String>,
206	    transpose_degrees: Option<i8>,
207	    prefer_above: Option<bool>,
208	    state: State<AppState>,
209	) -> Result<(), String> {
210	    let mut payload = serde_json::Map::new();
211	    if let Some(e) = enabled {
212	        payload.insert("enabled".into(), serde_json::json!(e));
213	    }
214	    if let Some(s) = species {
215	        payload.insert("species".into(), serde_json::json!(s));
216	    }
217	    if let Some(t) = transpose_degrees {
218	        payload.insert("transpose_degrees".into(), serde_json::json!(t));
219	    }
220	    if let Some(p) = prefer_above {
221	        payload.insert("prefer_above".into(), serde_json::json!(p));
222	    }
223	    let mut companion = state.companion.lock().map_err(|e| e.to_string())?;
224	    companion.configure_lane("counterpoint", serde_json::Value::Object(payload))
225	}
